import numpy as np

def akar_aman(x):
    return np.sqrt(np.maximum(x, 0))

import numpy as np

def bagi_aman(a, b):
    a = np.asarray(a, dtype=float)
    b = np.asarray(b, dtype=float)
    return np.divide(a, b, out=np.zeros(a.shape), where=b != 0)

import numpy as np

def bulatkan_dua(x):
    return np.round(x, 2).tolist()

import numpy as np

def hitung_tak_hingga(x):
    with np.errstate(all='ignore'):
        hasil = 1 / np.asarray(x, dtype=float)
    return int(np.isinf(hasil).sum())

import numpy as np

def total_kolom(a):
    return np.asarray(a).sum(axis=0).tolist()

import numpy as np

def rata_rata_valid(x):
    return float(np.nanmean(x))

import numpy as np

def jumlah_bergerak(x, k):
    return np.convolve(x, np.ones(k), 'valid').tolist()

import numpy as np

def batas_bawah(x, b):
    return np.maximum(x, b).tolist()

import numpy as np

def hampir_sama(a, b):
    return bool(np.allclose(a, b))

import numpy as np

def kategori(x):
    x = np.asarray(x)
    return np.select([x < 5, x < 10], [0, 1], default=2).tolist()

import numpy as np

def maks_berjalan(x):
    return np.maximum.accumulate(x).tolist()
